<div class="admin-welcome nursing-welcome">
    <div><p class="eyebrow">NURSING ASSESSMENT</p><h1 id="nursing-heading">Patient assessment</h1><p class="dashboard-subtitle">Record findings and select an existing clinical disposition.</p></div>
    <span class="nursing-date" data-current-date></span>
</div>
<section class="admin-panel nursing-assessment-panel" data-assessment-panel hidden aria-labelledby="assessment-heading">
    <div class="admin-panel-heading"><div><h2 id="assessment-heading">Patient nursing assessment</h2><p data-assessment-visit-summary></p></div><a class="button button-outline" href="queue.php">Back to queue</a></div>
    <div class="nursing-patient-summary" data-patient-summary></div>
    <section class="nursing-history" aria-labelledby="history-heading"><div class="nursing-subheading"><h3 id="history-heading">Relevant previous visits</h3><p>Recent visit and nursing information for this patient.</p></div><div class="table-wrap"><table class="admin-table nursing-history-table"><thead><tr><th>Visit date</th><th>Source</th><th>Status</th><th>Previous complaint / outcome</th></tr></thead><tbody data-history-rows></tbody></table></div></section>
    <section class="nursing-history nursing-clinical-history" aria-labelledby="allergies-heading"><div class="nursing-subheading"><h3 id="allergies-heading">Allergies</h3><p data-allergies>No allergy records are supported by the current database schema.</p></div></section>
    <section class="nursing-history nursing-clinical-history" aria-labelledby="doctor-history-heading"><div class="nursing-subheading"><h3 id="doctor-history-heading">Historical doctor notes</h3><p>These notes belong to previous visits and are read-only.</p></div><div class="table-wrap"><table class="admin-table nursing-history-table"><thead><tr><th>Visit / date</th><th>Type</th><th>Complaint / observations</th><th>Diagnosis / plan / notes</th></tr></thead><tbody data-doctor-history-rows></tbody></table></div></section>
    <section class="nursing-history nursing-clinical-history" aria-labelledby="test-history-heading"><div class="nursing-subheading"><h3 id="test-history-heading">Previous test results</h3><p>Results are from this patient's previous visits and are read-only.</p></div><div class="table-wrap"><table class="admin-table nursing-history-table"><thead><tr><th>Visit / result date</th><th>Test</th><th>Status</th><th>Result</th></tr></thead><tbody data-test-history-rows></tbody></table></div></section>
    <form class="nursing-form" data-assessment-form>
        <input type="hidden" name="visit_id">
        <div class="nursing-subheading nursing-form-heading"><h3>Complaints and symptoms</h3><p>Record the patient's account; do not enter a diagnosis in this section.</p></div>
        <div class="nursing-field nursing-field-wide"><label for="nursing-complaint">Main complaint</label><textarea id="nursing-complaint" name="complaint" rows="2" maxlength="5000"></textarea></div>
        <div class="nursing-field"><label for="nursing-symptoms">Symptoms</label><textarea id="nursing-symptoms" name="symptoms" rows="2" maxlength="10000"></textarea></div>
        <div class="nursing-field"><label for="nursing-duration">Duration of symptoms</label><input id="nursing-duration" name="symptom_duration" type="text" maxlength="100" placeholder="For example, 2 days"></div>
        <div class="nursing-subheading nursing-form-heading nursing-field-wide"><h3>Vital signs</h3><p>Optional; values are recorded without automated clinical interpretation.</p></div>
        <div class="nursing-field"><label for="nursing-temperature">Temperature (°C)</label><input id="nursing-temperature" name="temperature" type="number" min="25" max="45" step="0.1"></div>
        <fieldset class="nursing-field nursing-bp-field"><legend>Blood pressure (mmHg)</legend><div class="nursing-bp-inputs"><label><span class="visually-hidden">Systolic pressure</span><input name="systolic" type="number" min="40" max="300" step="1" placeholder="Systolic"></label><span aria-hidden="true">/</span><label><span class="visually-hidden">Diastolic pressure</span><input name="diastolic" type="number" min="20" max="200" step="1" placeholder="Diastolic"></label></div></fieldset>
        <div class="nursing-field"><label for="nursing-pulse">Pulse rate (bpm)</label><input id="nursing-pulse" name="pulse" type="number" min="1" max="300" step="1"></div>
        <div class="nursing-field"><label for="nursing-respiratory-rate">Respiratory rate (breaths/min)</label><input id="nursing-respiratory-rate" name="respiratory_rate" type="number" min="1" max="100" step="1"></div>
        <div class="nursing-field"><label for="nursing-oxygen">Oxygen saturation (%)</label><input id="nursing-oxygen" name="oxygen_saturation" type="number" min="0" max="100" step="0.1"></div>
        <div class="nursing-field"><label for="nursing-weight">Weight (kg)</label><input id="nursing-weight" name="weight" type="number" min="0.1" max="500" step="0.1"></div>
        <div class="nursing-field"><label for="nursing-height">Height (cm)</label><input id="nursing-height" name="height" type="number" min="20" max="250" step="0.1"></div>
        <div class="nursing-field nursing-field-wide"><label for="nursing-notes">Nursing notes / observations</label><textarea id="nursing-notes" name="nursing_notes" rows="3" maxlength="10000"></textarea></div>
        <div class="nursing-field nursing-field-wide"><button class="button button-outline" type="submit" data-save-assessment>Save Draft</button><span class="nursing-save-hint" data-save-hint></span></div>
    </form>
    <section class="nursing-decision-section" data-decision-section hidden aria-labelledby="decision-heading"><div class="nursing-subheading"><h3 id="decision-heading">Clinical next step</h3><p>Choose the appropriate existing workflow, then complete and submit the assessment.</p></div>
        <form class="nursing-form nursing-decision-form" data-decision-form><fieldset class="nursing-outcomes"><legend>Assessment outcome <span aria-hidden="true">*</span></legend><label><input type="radio" name="decision" value="minor_illness" required> Minor illness medication</label><label><input type="radio" name="decision" value="tests"> Refer for testing</label><label><input type="radio" name="decision" value="general_doctor"> Refer to doctor</label></fieldset>
            <fieldset class="nursing-test-options" data-test-options hidden><legend>Approved in-house tests</legend><label><input type="checkbox" name="test_types" value="blood"> Blood</label><label><input type="checkbox" name="test_types" value="glucose"> Glucose</label><label><input type="checkbox" name="test_types" value="urine"> Urine</label><label><input type="checkbox" name="test_types" value="pregnancy"> Pregnancy</label><label><input type="checkbox" name="test_types" value="pap_smear"> Pap smear</label><label><input type="checkbox" name="test_types" value="x_ray"> X-ray</label><label><input type="checkbox" name="test_types" value="ecg"> ECG</label></fieldset>
            <div class="nursing-field nursing-field-wide"><button class="button button-primary" type="submit" data-submit-decision>Complete Assessment and Submit</button></div>
        </form>
    </section>
    <section class="nursing-treatment-section" data-treatment-section hidden aria-labelledby="treatment-heading"><div class="nursing-subheading"><h3 id="treatment-heading">Minor illness prescription</h3><p>Only active low-schedule medicines are available. Pharmacy adds charges and deducts stock when it dispenses the paid prescription.</p></div>
        <form class="nursing-form nursing-treatment-form" data-treatment-form><div data-treatment-items></div><button class="button button-outline" type="button" data-add-treatment-item>Add medicine</button><div class="nursing-field nursing-field-wide"><label for="treatment-notes">Assessment / treatment notes</label><textarea id="treatment-notes" name="treatment_notes" rows="3" maxlength="5000"></textarea></div><div class="nursing-field nursing-field-wide"><button class="button button-primary" type="submit" data-save-treatment>Send prescription to Pharmacy</button></div></form>
    </section>
</section>